import org.jsoup.nodes.XmlDeclaration;
import java.io.Reader;
import java.util.List;

public class XmlTreeBuilderTest {

    private static XmlTreeBuilder treeBuilder;

    @BeforeClass
    public static void init() {
        Validate.noNullElements();
        treeBuilder = new XmlTreeBuilder();
    }

    public static void testParseWithReaderAndEmptyInput() {
        Reader reader = new StringReader("");
        Document document = treeBuilder.parse(reader, "");
        assertNotNull(document);
    }

    public static void testParseWithReaderAndValidXml() {
        Reader reader = new StringReader("<root><child/></root>");
        Document document = treeBuilder.parse(reader, "");
        assertNotNull(document);
        assertEquals("root", document.getDocumentElement().getNodeName());
    }

    public static void testInsertStartTag() {
        Token.StartTag startTag = new Token.StartTag();
        Element element = treeBuilder.insert(startTag);
        assertNotNull(element);
        assertTrue(element.getNodeName().equals(startTag.getTagName()));
    }

    public static void testInsertComment() {
        Token.Comment commentToken = new Token.Comment("comment");
        treeBuilder.insert(commentToken);
        assertNotNull(commentToken);
        assertTrue(commentToken.getNodeValue().equals("comment"));
    }

    public static void testPopStackToCloseEndTag() {
        Token.EndTag endTag = new Token.EndTag();
        treeBuilder.popStackToClose(endTag);
        assertTrue(treeBuilder.getStack().isEmpty());
    }

    public static void testParseFragmentWithEmptyInput() {
        List<Node> nodes = treeBuilder.parseFragment("", "", null, null);
        assertTrue(nodes.isEmpty());
    }

    public static void testParseFragmentWithValidXml() {
        String inputFragment = "<root><child/></root>";
        List<Node> nodes = treeBuilder.parseFragment(inputFragment, "", null, null);
        assertNotNull(nodes);
        assertEquals(1, nodes.size());
    }

    @Test
    public void testNewInstance() {
        XmlTreeBuilder newInstance = treeBuilder.newInstance();
        assertNotNull(newInstance);
    }
}
